"""Join original Native officer, ego, camera and PipelineCapture sources."""

from pathlib import Path
from queue import Empty, Queue

from officer_camera import CAMERAS, FourCameraEncoder
from officer_capture_sources import OfficerSourceWriter
from officer_direction import apply_direction


class NativeOfficerCapture:
    """One synchronized capture, with no inferred police or traffic-control labels."""

    def __init__(self, world, client, root, case_id, actors, context,
                 camera_blueprints, camera_mounts, required_atoms, direction_adapter,
                 frames, sizes=None, sensor_timeout_s=10,
                 encoder_factory=FourCameraEncoder,
                 writer_factory=OfficerSourceWriter, capture_factory=None):
        if (type(frames) is not int or frames < 3 or
                not isinstance(actors, dict) or "ego" not in actors or
                set(camera_blueprints) != set(CAMERAS) or
                set(camera_mounts) != set(CAMERAS) or
                context.get("case_id") != case_id or
                context.get("officer_actor_id") != getattr(actors.get("officer"), "id", None) or
                not isinstance(required_atoms, (list, tuple))):
            raise ValueError("Incomplete exact officer Native capture contract")
        self.world, self.client, self.root = world, client, Path(root)
        self.case_id, self.actors, self.context = case_id, actors, context
        self.camera_blueprints, self.camera_mounts = camera_blueprints, camera_mounts
        self.required_atoms, self.direction_adapter = required_atoms, direction_adapter
        self.frames, self.sizes, self.sensor_timeout_s = frames, sizes, sensor_timeout_s
        self.encoder_factory, self.writer_factory = encoder_factory, writer_factory
        self.capture_factory = capture_factory
        self.sensors, self.queues = {}, {}
        self.encoder = self.writer = self.pipeline_capture = None
        self.count = 0

    def __enter__(self):
        try:
            for name in CAMERAS:
                mount = self.camera_mounts[name]
                if set(mount) != {"transform", "attach_to"} or mount["attach_to"] not in (None, "ego", "through", "officer"):
                    raise ValueError("Invalid original officer camera mount: " + name)
                parent = self.actors.get(mount["attach_to"])
                if mount["attach_to"] is not None and parent is None:
                    raise ValueError("Camera attachment actor missing: " + name)
                options = {} if parent is None else {"attach_to": parent}
                sensor = self.world.spawn_actor(self.camera_blueprints[name], mount["transform"], **options)
                if sensor is None:
                    raise ValueError("Original officer camera spawn failed: " + name)
                self.sensors[name] = sensor
                self.queues[name] = Queue()
                sensor.listen(self.queues[name].put)
            self.encoder = self.encoder_factory(self.root, sizes=self.sizes)
            self.encoder.__enter__()
            self.writer = self.writer_factory(self.root, self.context)
            self.writer.__enter__()
            if self.capture_factory is None:
                from pipeline_capture import PipelineCapture
                self.capture_factory = PipelineCapture
            self.pipeline_capture = self.capture_factory(
                self.client, self.actors["ego"], self.root, self.case_id,
                required_observations=self.required_atoms)
            return self
        except BaseException:
            self._close(abort=True)
            raise

    def capture_tick(self):
        if self.count >= self.frames:
            raise ValueError("Officer capture exceeds selected frame plan")
        pose = apply_direction(self.actors.get("officer"), self.direction_adapter,
                               self.case_id, self.count, self.frames)
        frame = self.world.tick()
        if type(frame) is not int:
            raise ValueError("Native tick has no integer frame identity")
        packets = {}
        for name in CAMERAS:
            try:
                packet = self.queues[name].get(timeout=self.sensor_timeout_s)
            except Empty as exc:
                raise ValueError("Original officer camera frame missing: " + name) from exc
            if packet.frame != frame:
                raise ValueError("Original officer camera frame differs: " + name)
            packets[name] = packet
        self.encoder.validate_packets(packets)
        snapshot = self.world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError("Native snapshot differs from camera frame")
        row = self.writer.add_tick(snapshot, packets, self.actors["ego"],
                                   self.actors.get("officer"), pose,
                                   through=self.actors.get("through"))
        self.encoder.add_packets(packets)
        self.pipeline_capture.capture(frame, row["time_s"])
        self.count += 1
        return row

    def _close(self, abort):
        failure = None
        if self.pipeline_capture is not None:
            try:
                self.pipeline_capture.close(confirmed=not abort)
            except BaseException as exc:
                failure = exc
        if self.writer is not None:
            try:
                self.writer.__exit__(None, None, None)
            except BaseException as exc:
                failure = failure or exc
        for sensor in reversed(list(self.sensors.values())):
            try:
                sensor.stop()
                sensor.destroy()
            except BaseException as exc:
                failure = failure or exc
        if self.encoder is not None and self.encoder.processes:
            try:
                self.encoder._finish(abort=abort or failure is not None)
            except BaseException as exc:
                failure = failure or exc
        if failure is not None:
            raise failure

    def __exit__(self, kind, value, trace):
        self._close(abort=kind is not None or self.count != self.frames)
        if kind is None and self.count != self.frames:
            raise ValueError("Officer capture ended before selected frame plan")
        return False

"""Four original lossless Native camera streams for C157964 officer review."""

from pathlib import Path
import subprocess

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
CAMERA_SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
                "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


class FourCameraEncoder:
    """Retain four original BGRA sensor streams in lossless FFV1 containers."""

    def __init__(self, root, sizes=None, fps=20):
        self.root = Path(root)
        self.sizes = dict(CAMERA_SIZES if sizes is None else sizes)
        if set(self.sizes) != set(CAMERAS) or type(fps) is not int or fps <= 0:
            raise ValueError("Four named camera dimensions and integer rate required")
        if any(not isinstance(size, (tuple, list)) or len(size) != 2 or
               any(type(v) is not int or v <= 0 for v in size)
               for size in self.sizes.values()):
            raise ValueError("Invalid camera dimensions")
        self.fps = fps
        self.processes = {}
        self.count = 0

    def __enter__(self):
        self.root.mkdir(parents=True, exist_ok=True)
        if any((self.root / (name + ".mkv")).exists() for name in CAMERAS):
            raise ValueError("Original camera video already exists")
        try:
            for name in CAMERAS:
                width, height = self.sizes[name]
                command = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                           "-f", "rawvideo", "-pixel_format", "bgra", "-video_size",
                           f"{width}x{height}", "-framerate", str(self.fps),
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-level", "3",
                           "-pix_fmt", "bgr0", str(self.root / (name + ".mkv"))]
                self.processes[name] = subprocess.Popen(command, stdin=subprocess.PIPE,
                                                        stdout=subprocess.DEVNULL,
                                                        stderr=subprocess.PIPE)
        except Exception:
            self._finish(abort=True)
            raise
        return self

    def validate_packets(self, packets):
        if set(packets) != set(CAMERAS):
            raise ValueError("Four original camera packets required")
        for name in CAMERAS:
            packet = packets[name]
            width, height = self.sizes[name]
            if (packet.width, packet.height) != (width, height) or len(packet.raw_data) != width * height * 4:
                raise ValueError("Camera pixels differ from capture profile: " + name)

    def add_packets(self, packets):
        self.validate_packets(packets)
        for name in CAMERAS:
            self.processes[name].stdin.write(packets[name].raw_data)
        self.count += 1

    def _finish(self, abort=False):
        failures = []
        self.exit_codes = {}
        processes, self.processes = self.processes, {}
        for name, process in processes.items():
            if abort:
                if process.poll() is None:
                    process.kill()
            process.stdin.close()
            stderr = process.stderr.read().decode("utf-8", errors="replace")
            process.stderr.close()
            code = process.wait()
            self.exit_codes[name] = code
            if not abort and (code != 0 or not (self.root / (name + ".mkv")).is_file()):
                failures.append(name + ": " + stderr[-400:])
        if failures:
            raise ValueError("Four-camera FFV1 encoding failed: " + "; ".join(failures))

    def __exit__(self, kind, value, trace):
        self._finish(abort=kind is not None)
        return False

"""Per-frame officer direction program for the exact exception comparisons.

The caller supplies a Native bone-pose adapter reviewed for the selected walker.
The adapter must move the visible arm bones and report the realized pose. A
programmed direction is never substituted for an original-camera observation.
"""

from dataclasses import dataclass
import math


SUFFIXES = (
    "officer_active_stop_then_go",
    "officer_active_hold",
    "officer_present_inactive",
    "no_officer_yield_nearest_view",
)
PREFIX = "testing__C157964__NRS-484B-257-1__motor_vehicle_driver__"


@dataclass(frozen=True)
class DirectionPhase:
    start_frame: int
    end_frame: int
    direction: str


def phases(case_id: str, frames: int = 600) -> tuple[DirectionPhase, ...]:
    if type(frames) is not int or frames < 3:
        raise ValueError("Officer program needs a complete 20 Hz capture")
    suffix = case_id[len(PREFIX):] if isinstance(case_id, str) and case_id.startswith(PREFIX) else None
    if suffix not in SUFFIXES:
        raise ValueError("Unknown exact officer case")
    if suffix == "officer_active_stop_then_go":
        switch = frames // 2
        return (DirectionPhase(0, switch, "stop"),
                DirectionPhase(switch, frames, "go"))
    if suffix == "officer_active_hold":
        return (DirectionPhase(0, frames, "stop"),)
    return (DirectionPhase(0, frames, "none"),)


def apply_direction(actor, adapter, case_id: str, frame_index: int,
                    frames: int = 600) -> dict:
    """Apply an explicit visible-bone pose and retain its Native readback.

    ``adapter`` takes (actor, direction) and returns a source-shaped readback
    with the same actor ID, pose name and at least one realized bone transform.
    It must raise when the selected walker lacks the necessary Native API.
    """
    if type(frame_index) is not int or not 0 <= frame_index < frames:
        raise ValueError("Officer direction frame outside capture")
    direction = next(p.direction for p in phases(case_id, frames)
                     if p.start_frame <= frame_index < p.end_frame)
    if direction == "none":
        if actor is not None and type(getattr(actor, "id", None)) is not int:
            raise ValueError("Native officer identity missing")
        if case_id.endswith("__no_officer_yield_nearest_view") and actor is not None:
            raise ValueError("No-officer baseline contains an officer actor")
        if case_id.endswith("__officer_present_inactive") and actor is None:
            raise ValueError("Inactive-officer comparison lacks the officer actor")
        return {"frame_index": frame_index, "officer_actor_id": getattr(actor, "id", None),
                "programmed_direction": "none", "pose_applied": False}
    if actor is None or type(getattr(actor, "id", None)) is not int:
        raise ValueError("Native officer identity missing")
    if adapter is None:
        raise ValueError("Native visible-bone direction adapter missing")
    readback = adapter(actor, direction)
    if (not isinstance(readback, dict) or
            readback.get("officer_actor_id") != actor.id or
            readback.get("direction") != direction or
            not isinstance(readback.get("realized_bones"), dict) or
            not readback["realized_bones"]):
        raise ValueError("Native officer direction pose readback missing")
    return {"frame_index": frame_index, "officer_actor_id": actor.id,
            "programmed_direction": direction, "pose_applied": True,
            "realized_bones": readback["realized_bones"]}


def native_bone_adapter(carla, stop_pose: dict, go_pose: dict):
    """Create the Native walker adapter from reviewed, named arm rotations.

    Pose maps use walker bone names as keys and pitch/yaw/roll degrees as values.
    The selected walker must expose those bones; unsupported walkers fail before
    capture is sealed. Bone readback proves API application, not visible pixels.
    """
    poses = {"stop": stop_pose, "go": go_pose}
    if not all(isinstance(p, dict) and p for p in poses.values()):
        raise ValueError("Both visible-direction bone poses are required")
    for pose in poses.values():
        for name, angles in pose.items():
            if (not isinstance(name, str) or not name or not isinstance(angles, dict) or
                    set(angles) != {"pitch", "yaw", "roll"}):
                raise ValueError("Named officer arm bone rotation required")
            if any(type(value) not in (int, float) or not math.isfinite(value)
                   for value in angles.values()):
                raise ValueError("Officer bone rotation must be finite")

    def bone_parts(entry):
        if hasattr(entry, "name") and hasattr(entry, "relative"):
            return entry.name, entry.relative
        if isinstance(entry, (tuple, list)) and len(entry) >= 3:
            return entry[0], entry[2]
        raise ValueError("Unsupported Native walker bone readback shape")

    def apply(actor, direction):
        if direction not in poses:
            raise ValueError("Unsupported officer direction")
        original = actor.get_bones()
        available = {bone_parts(entry)[0] for entry in original.bone_transforms}
        missing = set(poses[direction]) - available
        if missing:
            raise ValueError("Selected walker lacks officer arm bones: " + ", ".join(sorted(missing)))
        updates = [(name, carla.Transform(rotation=carla.Rotation(**angles)))
                   for name, angles in poses[direction].items()]
        actor.set_bones(carla.WalkerBoneControl(updates))
        actor.blend_pose(1.0)
        readback = {name: relative.rotation
                    for entry in actor.get_bones().bone_transforms
                    for name, relative in [bone_parts(entry)]
                    if name in poses[direction]}
        if set(readback) != set(poses[direction]):
            raise ValueError("Native officer arm-bone readback incomplete")
        realized = {name: {axis: float(getattr(rotation, axis))
                           for axis in ("pitch", "yaw", "roll")}
                    for name, rotation in readback.items()}
        for name, target in poses[direction].items():
            if any(not math.isfinite(realized[name][axis]) or
                   abs(realized[name][axis] - target[axis]) > 2.0
                   for axis in ("pitch", "yaw", "roll")):
                raise ValueError("Native officer arm-bone pose differs from command")
        return {"officer_actor_id": actor.id, "direction": direction,
                "realized_bones": realized}

    return apply

"""Spawn a source-reviewed officer performer at a surveyed junction position.

A pedestrian blueprint and costume are not proof of police authority or actual
traffic control. Those require original-camera and provenance review.
"""

from contextlib import contextmanager
import math


def _distance(a,b):
    return math.sqrt((a.x-b.x)**2+(a.y-b.y)**2+(a.z-b.z)**2)


@contextmanager
def spawn_officer_performer(world, blueprint, transform, junction_center,
                            *, min_clearance_m=2.0, max_distance_m=20.0):
    point=transform.location
    distance=_distance(point,junction_center)
    if not math.isfinite(distance) or distance<min_clearance_m or distance>max_distance_m:
        raise ValueError("Officer placement outside surveyed junction band")
    actor=world.try_spawn_actor(blueprint,transform)
    if actor is None:raise ValueError("Native officer performer spawn failed")
    try:
        realized=actor.get_location()
        if _distance(realized,point)>1.0:
            raise ValueError("Realized officer location differs from surveyed placement")
        yield {"actor":actor,"surveyed_distance_to_junction_m":distance,
               "realized_location":realized}
    finally:
        actor.destroy()

"""Original-frame officer-control observations for the statutory exception.

Camera-visible direction and timing are evidence; legal police authority and
whether traffic was actually controlled remain source-review judgments.
"""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon


CAMERAS=("overview","approach","reference_corner","driver_reference")
REQUIRED=("officer_context.json","officer_history.jsonl","video_frames.jsonl",
          "officer_review.json")
PREFIX="testing__C157964__NRS-484B-257-1__motor_vehicle_driver__"
ACTIVE={PREFIX+"officer_active_stop_then_go",PREFIX+"officer_active_hold"}
INACTIVE=PREFIX+"officer_present_inactive"
ABSENT=PREFIX+"no_officer_yield_nearest_view"


def _number(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError("Missing finite "+label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def analyze(root:Path)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError("Missing original source: "+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    review=json.loads((root/"officer_review.json").read_text())
    if (review.get("officer_history_sha256")!=hashes["officer_history.jsonl"] or
            review.get("video_frames_sha256")!=hashes["video_frames.jsonl"]):
        raise ValueError("Officer review source hash differs")
    cameras=review.get("camera_sha256")
    if not isinstance(cameras,dict) or set(cameras)!=set(CAMERAS):
        raise ValueError("Four original camera hashes required")
    for camera in CAMERAS:
        path=root/(camera+".mkv")
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=cameras[camera]:
            raise ValueError("Original officer camera bytes differ: "+camera)
        hashes[camera+".mkv"]=cameras[camera]
    ctx=json.loads((root/"officer_context.json").read_text())
    case_id=ctx.get("case_id")
    if case_id not in ACTIVE|{INACTIVE,ABSENT}:
        raise ValueError("Unknown exact officer case identity")
    for key in ("native_map_id","intersection_id","direction_video_source",
                "junction_source","ego_route_source"):
        if not ctx.get(key):raise ValueError("Missing sourced officer context: "+key)
    if case_id==ABSENT:
        if any(ctx.get(key) is not None for key in ("officer_actor_id","authority_source","uniform_video_source")):
            raise ValueError("No-officer baseline must lack officer identity and authority")
    else:
        for key in ("officer_actor_id","authority_source","uniform_video_source"):
            if not ctx.get(key):raise ValueError("Missing sourced officer context: "+key)
    polygon=Polygon(ctx.get("intersection_polygon_xy_m",[]))
    if not polygon.is_valid or polygon.area<=0:raise ValueError("Invalid intersection polygon")
    rows,frames=_rows(root/"officer_history.jsonl"),_rows(root/"video_frames.jsonl")
    observations=review.get("frames")
    if (len(rows)<3 or len(rows)!=len(frames) or
            not isinstance(observations,list) or len(observations)!=len(rows)):
        raise ValueError("Incomplete officer/ego camera history")
    previous=(-1,-math.inf);samples=[];first_entry=None
    for i,(row,frame,observed) in enumerate(zip(rows,frames,observations)):
        fid,time=row.get("frame"),_number(row.get("time_s"),"time")
        if type(fid) is not int or fid<=previous[0] or time<=previous[1]:
            raise ValueError("Nonmonotone original history")
        previous=fid,time
        if frame.get("video_frame")!=i or frame.get("carla_frame")!=fid or frame.get("time_s")!=time:
            raise ValueError("Original frame join failed")
        if (set(frame.get("camera_frames",{}))!=set(CAMERAS) or
                any(frame["camera_frames"][camera]!=fid for camera in CAMERAS)):
            raise ValueError("Four original camera frame joins required")
        if row.get("officer_actor_id")!=ctx["officer_actor_id"]:
            raise ValueError("Officer actor identity mismatch")
        instruction=observed.get("observed_direction")
        if instruction not in ("stop","go","unclear","none"):
            raise ValueError("Missing original officer direction observation")
        if (observed.get("frame")!=fid or observed.get("video_frame")!=i or
                type(observed.get("officer_visible")) is not bool):
            raise ValueError("Officer camera review direction/frame join failed")
        if "officer_direction_observed" in row or "traffic_control_observed" in row:
            raise ValueError("Capture history must not prelabel camera observations")
        source=observed.get("direction_frame_source")
        if not source:raise ValueError("Missing direction video frame source")
        controlled=observed.get("traffic_control_observed")
        if type(controlled) is not bool:raise ValueError("Missing original control observation")
        if case_id==ABSENT and (controlled or instruction!="none" or observed["officer_visible"]):
            raise ValueError("No-officer baseline contradicts original camera review")
        if case_id==INACTIVE and (controlled or instruction in ("stop","go") or
                                  not observed["officer_visible"]):
            raise ValueError("Inactive officer baseline contradicts original camera review")
        if controlled and (not observed["officer_visible"] or instruction=="unclear"):
            raise ValueError("Claimed active officer control lacks a visible direction")
        if controlled and instruction=="none":
            raise ValueError("Claimed active officer control lacks a direction")
        ego=row.get("ego")
        if not isinstance(ego,dict):raise ValueError("Missing ego source")
        speed=_number(ego.get("speed_mps"),"ego speed")
        if speed<0:raise ValueError("Negative ego speed")
        through_id=ctx.get("through_actor_id")
        through_speed=None
        if through_id is not None:
            through=row.get("through")
            if not isinstance(through,dict) or through.get("actor_id")!=through_id:
                raise ValueError("Original through actor identity missing")
            through_speed=_number(through.get("speed_mps"),"through speed")
            points=through.get("body_vertices_xy_m")
            if through_speed<0 or not isinstance(points,list) or len(points)<8:
                raise ValueError("Complete original through body and motion required")
            for point in points:
                if not isinstance(point,list) or len(point)!=2:
                    raise ValueError("Original through body vertex missing")
                _number(point[0],"through body x")
                _number(point[1],"through body y")
        vertices=ego.get("body_vertices_xy_m")
        if not isinstance(vertices,list) or len(vertices)<4:raise ValueError("Missing complete ego body")
        body=MultiPoint([(_number(p[0],"body x"),_number(p[1],"body y")) for p in vertices]).convex_hull
        inside=body.intersects(polygon)
        if i==0 and inside:raise ValueError("Missing pre-entry approach")
        if inside and first_entry is None:first_entry={"frame":fid,"time_s":time,
                                                       "officer_direction_observed":instruction,
                                                       "traffic_control_observed":controlled,
                                                       "officer_visible":observed["officer_visible"]}
        samples.append({"frame":fid,"time_s":time,"direction":instruction,
                        "traffic_control_observed":controlled,"ego_speed_mps":speed,
                        "ego_body_in_intersection":inside,
                        "through_speed_mps":through_speed})
    if first_entry is None:raise ValueError("No observed ego entry")
    fixed={key:ctx[key] for key in ("native_map_id","intersection_id",
                                   "intersection_polygon_xy_m","ego_route_source",
                                   "junction_source","direction_video_source")}
    if ctx.get("through_actor_id") is not None:
        if not ctx.get("through_route_source"):
            raise ValueError("Missing sourced through route")
        fixed["through_route_source"]=ctx["through_route_source"]
    return {"format":"worker-officer-control-exception-observations","case_id":case_id,
            "sources":hashes,
            "fixed_context":fixed,
            "first_ego_entry":first_entry,"officer_control_observed_at_entry":first_entry["traffic_control_observed"],
            "samples":samples,"police_authority_judgment":(
                "not applicable; no officer actor" if case_id==ABSENT else
                "unresolved pending source review"),
            "legal_control_exception_judgment":"unresolved","legal_conclusion":"unresolved"}

"""Source-bound signed-entrance observations; no legal judgment is computed."""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _finite(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Missing finite " + label)
    return float(value)


def analyze(attempt, config, history, frames, review):
    attempt = Path(attempt)
    site = config["site"]
    source = attempt / "officer-site.xodr"
    if not source.is_file() or _sha(source) != site["xodr_sha256"]:
        raise ValueError("Signed entrance OpenDRIVE source differs")
    site_review = review.get("site_review")
    if not isinstance(site_review, dict) or site_review.get("sign_id") != site["yield_sign_id"]:
        raise ValueError("Missing exact signed-entrance review")
    if site_review.get("sign_face_observed") not in ("yield", "stop", "unverified"):
        raise ValueError("Missing original sign-face review")
    if site_review.get("proper_sign_judgment") != "unresolved" or site_review.get("nearest_view_judgment") != "unresolved":
        raise ValueError("Signed entrance review must preserve unresolved judgments")
    if site_review.get("source_camera") not in (name + ".mkv" for name in CAMERAS):
        raise ValueError("Signed entrance review needs original camera source")
    officer_context = json.loads((attempt / "officer_context.json").read_text())
    polygon = Polygon(officer_context["intersection_polygon_xy_m"])
    if not polygon.is_valid or polygon.area <= 0 or len(history) != len(frames) or len(history) != len(review["frames"]):
        raise ValueError("Incomplete signed-entrance source history")
    channels = {name: [] for name in (
        "through_highway_sight_clear", "ego_distance_to_junction_m",
        "through_vehicle_position", "through_vehicle_speed",
        "ego_crossing_body", "ego_approach_speed")}
    for row, frame, observed in zip(history, frames, review["frames"]):
        fid, time = row.get("frame"), _finite(row.get("time_s"), "site time")
        if fid != frame.get("carla_frame") or fid != observed.get("frame") or time != frame.get("time_s"):
            raise ValueError("Signed-entrance camera/history join failed")
        sight = observed.get("through_highway_sight_clear")
        if type(sight) is not bool or observed.get("sight_frame_source") not in (name + ".mkv" for name in CAMERAS):
            raise ValueError("Missing original through-highway sight review")
        ego, through = row.get("ego"), row.get("through")
        if not isinstance(ego, dict) or not isinstance(through, dict):
            raise ValueError("Missing ego/through source bodies")
        if through.get("actor_id") != officer_context["through_actor_id"]:
            raise ValueError("Through actor differs from signed-entrance source")
        ego_points, through_points = ego.get("body_vertices_xy_m"), through.get("body_vertices_xy_m")
        if not isinstance(ego_points, list) or len(ego_points) < 4 or not isinstance(through_points, list) or len(through_points) < 4:
            raise ValueError("Incomplete original crossing bodies")
        ego_body = MultiPoint([(_finite(p[0], "ego x"), _finite(p[1], "ego y")) for p in ego_points]).convex_hull
        through_body = MultiPoint([(_finite(p[0], "through x"), _finite(p[1], "through y")) for p in through_points]).convex_hull
        values = {
            "through_highway_sight_clear": int(sight),
            "ego_distance_to_junction_m": ego_body.distance(polygon),
            "through_vehicle_position": {"body_vertices_xy_m": through_points, "center_xy_m": list(through_body.centroid.coords[0])},
            "through_vehicle_speed": {"speed_mps": _finite(through.get("speed_mps"), "through speed")},
            "ego_crossing_body": {"body_vertices_xy_m": ego_points, "inside_junction": ego_body.intersects(polygon)},
            "ego_approach_speed": _finite(ego.get("speed_mps"), "ego speed"),
        }
        for name, value in values.items():
            channels[name].append({"original_frame": fid, "time_s": time, "value": value})
    source_hashes = {name: _sha(attempt / name) for name in (
        "officer-site.xodr", "officer_history.jsonl", "officer_review.json", "video_frames.jsonl")}
    source_hashes.update({name + ".mkv": _sha(attempt / (name + ".mkv")) for name in CAMERAS})
    context = {"yield_site_review": {
        "sign_id": site["yield_sign_id"], "sign_face_observed": site_review["sign_face_observed"],
        "source_camera": site_review["source_camera"],
        "stop_line_observed": site_review.get("stop_line_observed"),
        "crosswalk_observed": site_review.get("crosswalk_observed"),
        "proper_sign_judgment": "unresolved", "nearest_view_judgment": "unresolved",
        "immediate_hazard_judgment": "unresolved", "right_of_way_judgment": "unresolved",
        "review_provenance_kind": review.get("provenance_kind"), "source_sha256": source_hashes}}
    return channels, context

